/// How many there are.
pub const REMAINING_COUNT: usize = 1262;

/// Implements part of the remainder.
///
/// What one routine does, if it is one of these.
#[must_use]
pub fn routine_at(routine: u32) -> Option<&'static Routine> {
    REMAINING
        .binary_search_by_key(&routine, |held| held.routine)
        .ok()
        .map(|at| &REMAINING[at])
}

/// Implements part of the remainder.
///
/// How deep one routine goes.
#[must_use]
pub fn deepest(held: &Routine) -> u8 {
    held.steps.iter().map(|step| step.depth).max().unwrap_or(0)
}

/// Implements part of the remainder.
///
/// Whether a routine asks no question at all: a straight run of calls.
#[must_use]
pub fn asks_nothing(held: &Routine) -> bool {
    held.steps
        .iter()
        .all(|step| step.does == Does::Straightaway)
}

/// Implements part of the remainder.
///
/// How many times a routine asks what class something is.
#[must_use]
pub fn class_tests_in(held: &Routine) -> usize {
    held.steps
        .iter()
        .flat_map(|step| step.calls.iter())
        .filter(|call| **call == ASKS_WHAT_CLASS)
        .count()
}

/// Implements part of the remainder.
///
/// Every routine that tries one class after another.
///
/// A Delphi `is` cascade: each test nested inside the last one's failure, which
/// is what `else if` compiles to when no table can be made of it. Depth here is
/// a list rather than complexity.
#[must_use]
pub fn class_cascades() -> Vec<&'static Routine> {
    REMAINING
        .iter()
        .filter(|held| class_tests_in(held) >= 3)
        .collect()
}

/// Implements part of the remainder.
///
/// Whether a routine is a constructor.
#[must_use]
pub fn is_a_constructor(held: &Routine) -> bool {
    held.steps
        .iter()
        .any(|step| step.calls.contains(&MAKES_AN_INSTANCE))
        && held
            .steps
            .iter()
            .any(|step| step.calls.contains(&AFTER_IT_IS_MADE))
}

/// Implements part of the remainder.
///
/// Every routine that is a constructor.
#[must_use]
pub fn constructors() -> Vec<&'static Routine> {
    REMAINING
        .iter()
        .filter(|held| is_a_constructor(held))
        .collect()
}

/// Implements part of the remainder.
///
/// Whether the two halves of a constructor sit in different steps.
#[must_use]
pub fn halves_are_apart(held: &Routine) -> bool {
    let makes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&MAKES_AN_INSTANCE));
    let finishes = held
        .steps
        .iter()
        .position(|step| step.calls.contains(&AFTER_IT_IS_MADE));
    match (makes, finishes) {
        (Some(one), Some(other)) => one != other,
        _ => false,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_count_is_what_the_table_holds() {
        assert_eq!(REMAINING.len(), REMAINING_COUNT);
    }

    #[test]
    fn the_table_is_sorted_so_it_can_be_searched() {
        assert!(
            REMAINING
                .windows(2)
                .all(|pair| pair[0].routine < pair[1].routine)
        );
    }

    #[test]
    fn a_routine_can_be_found_by_its_address() {
        let known = REMAINING[0].routine;

        assert!(routine_at(known).is_some());
        assert!(routine_at(0).is_none());
    }

    #[test]
    fn none_of_these_was_taken_by_a_shaped_table() {
        for held in REMAINING.iter().take(400) {
            assert!(crate::nested_routines::routine_at(held.routine).is_none());
            assert!(crate::deeper_routines::routine_at(held.routine).is_none());
            assert!(crate::looping_routines::routine_at(held.routine).is_none());
            assert!(crate::substantial_routines::routine_at(held.routine).is_none());
            assert!(crate::unaided_routines::routine_at(held.routine).is_none());
        }
    }

    #[test]
    fn every_recorded_call_is_a_function_that_was_recovered() {
        for held in &REMAINING {
            for call in held.steps.iter().flat_map(|step| step.calls.iter()) {
                assert!(
                    (FIRST_RECOVERED..=LAST_RECOVERED).contains(call),
                    "{call:#010X} in {:#010X}",
                    held.routine
                );
            }
        }
    }

    #[test]
    fn the_depths_of_a_routine_only_ever_step_down_by_one() {
        for held in &REMAINING {
            let mut last = 0_u8;
            for step in held.steps {
                assert!(step.depth <= last + 1, "{:#010X}", held.routine);
                last = step.depth;
            }
        }
    }

    #[test]
    fn most_of_them_ask_no_question_at_all() {
        let straight = REMAINING.iter().filter(|held| asks_nothing(held)).count();

        assert!(
            straight * 2 > REMAINING.len(),
            "{straight} of {}",
            REMAINING.len()
        );
    }

    #[test]
    fn a_routine_that_asks_nothing_has_only_straightaway_steps() {
        for held in REMAINING.iter().filter(|held| asks_nothing(held)).take(100) {
            for step in held.steps {
                assert_eq!(step.does, Does::Straightaway);
            }
        }
    }

    #[test]
    fn the_deepest_routine_anywhere_is_in_here() {
        let here = REMAINING.iter().map(deepest).max().expect("some");
        let substantial = crate::substantial_routines::SUBSTANTIAL
            .iter()
            .map(crate::substantial_routines::deepest)
            .max()
            .expect("some");

        assert!(here > substantial, "{here} against {substantial}");
    }

    #[test]
    fn and_its_depth_is_a_list_of_class_tests_rather_than_complexity() {
        // Each test nested inside the last one's failure: a Delphi `is`
        // cascade, which is what `else if` compiles to when no table can be
        // made of it.
        let deepest_here = REMAINING
            .iter()
            .max_by_key(|held| deepest(held))
            .expect("some routine is the deepest");

        assert!(
            class_tests_in(deepest_here) >= 3,
            "{:#010X} asks {} times",
            deepest_here.routine,
            class_tests_in(deepest_here)
        );
    }

    #[test]
    fn some_routines_try_one_class_after_another() {
        let cascading = class_cascades();

        assert!(!cascading.is_empty());
        for held in &cascading {
            assert!(class_tests_in(held) >= 3, "{:#010X}", held.routine);
        }
    }

    #[test]
    fn a_routine_that_never_asks_what_class_is_not_a_cascade() {
        let plain = REMAINING
            .iter()
            .find(|held| class_tests_in(held) == 0)
            .expect("some routine never asks");

        assert!(
            !class_cascades()
                .iter()
                .any(|held| held.routine == plain.routine)
        );
    }

    #[test]
    fn some_of_them_are_constructors() {
        assert!(!constructors().is_empty());
    }

    #[test]
    fn and_in_every_one_the_two_halves_sit_in_different_steps() {
        for held in constructors() {
            assert!(halves_are_apart(held), "{:#010X}", held.routine);
        }
    }

    #[test]
    fn every_routine_calls_something_somewhere() {
        for held in &REMAINING {
            assert!(
                held.steps.iter().any(|step| !step.calls.is_empty()),
                "{:#010X}",
                held.routine
            );
        }
    }

    #[test]
    fn every_routine_is_listed_once() {
        let mut routines: Vec<u32> = REMAINING.iter().map(|held| held.routine).collect();
        let before = routines.len();
        routines.sort_unstable();
        routines.dedup();

        assert_eq!(routines.len(), before);
    }
}
